SELECT sri.id, sri.source_id AS sourceId, srid.source_detail_id AS sourceDetailId, srid.so_return_detail_id AS soReturnDetailId, sri.so_return_id as soReturnId, sri.code, sri.source_code AS sourceCode, sri.so_code AS soCode, sri.type, sri.customer_id AS customerId, sri.customer_name AS customerName, sri.approve_status AS approveStatus, sri.invalid_status AS invalidStatus, sri.seller_id AS sellerId, sri.seller_name AS sellerName, sri.so_id as soId, srid.id as detailId, srid.sku_id AS skuId, srid.sku_no AS skuNo, srid.return_type_dict AS returnTypeDict, srid.must_qty AS mustQty, srid.receive_qty AS receiveQty, srid.real_qty AS realQty, sri.bill_date AS billDate, sri.approve_user_name AS approveUserName, sri.create_user_name AS createUserName, sri.create_time AS createTime, sri.inventory_org_id AS inventoryOrgId, sri.inventory_org_name AS inventoryOrgName, srid.is_sub_contract AS isSubContract, sri.third_code as thirdCode, sri.return_logistic_code as returnLogisticCode, sb2c.platform_code as platformOrderCode FROM so_return_instock_detail srid INNER JOIN so_return_instock sri ON sri.id = srid.main_id LEFT JOIN so_b2c sb2c on sb2c.id = sri.so_id and sb2c.is_deleted = false WHERE ${params.sqlMap.default} and srid.is_deleted = FALSE AND sri.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sri.create_time desc

select
count(distinct sri.id)
FROM so_return_instock sri
INNER JOIN so_return_instock_detail srid ON sri.id = srid.main_id AND sri.is_deleted = FALSE
WHERE srid.is_deleted = FALSE

    and sri.approve_status in

        #{item}



    and sri.bill_date >= #{params.billDateList[0]} and  (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sri.bill_date


    and sri.invalid_status = #{params.invalidStatus}


    ${params.permissionSql}

SELECT sri.id, sri.source_id AS sourceId, srid.source_detail_id AS sourceDetailId, srid.so_return_detail_id AS soReturnDetailId, sri.code, sri.source_code AS sourceCode, sri.so_code AS soCode, sri.type, sri.customer_id AS customerId, sri.customer_name AS customerName, sri.approve_status AS approveStatus, sri.invalid_status AS invalidStatus, sri.seller_id AS sellerId, sri.seller_name AS sellerName, srid.sku_id AS skuId, srid.sku_no AS skuNo, srid.return_type_dict AS returnTypeDict, srid.must_qty AS mustQty, srid.receive_qty AS receiveQty, srid.real_qty AS realQty, sri.bill_date AS billDate, sri.approve_user_name AS approveUserName, sri.create_user_name AS createUserName, sri.create_time AS createTime, sri.inventory_org_id AS inventoryOrgId, sri.inventory_org_name AS inventoryOrgName, sri.third_code as thirdCode, sri.return_logistic_code as returnLogisticCode FROM so_return_instock sri INNER JOIN so_return_instock_detail srid ON sri.id = srid.main_id AND sri.is_deleted = FALSE WHERE ${params.sqlMap.default} and srid.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sri.create_time desc

SELECT DISTINCT sri.id, sri.code, sri.source_type, sri.approve_status, sri.warehouse_name, sri.seller_name, sri.create_time FROM so_return_instock sri INNER JOIN so_return_instock_detail srid ON sri.id = srid.main_id AND srid.is_deleted = FALSE WHERE sri.is_deleted = FALSE AND sri.invalid_status = FALSE
and sri.approve_status in
#{item}
and sri.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sri.bill_date
${params.permissionSql}
${item.field} ${item.sort}
ORDER BY sri.create_time desc
